public class InnerConnectionTypeFilterConfigurationFactory(Action<Humidifier.Glue.ConnectionTypeTypes.FilterConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.Glue.ConnectionTypeTypes.FilterConfiguration>
{

    internal InnerConnectionTypeBetweenConfigurationFactory BetweenConfigurationFactory { get; set; }

    internal InnerConnectionTypeFilterStringConfigurationFactory FilterStringConfigurationFactory { get; set; }

    protected override Humidifier.Glue.ConnectionTypeTypes.FilterConfiguration Create()
    {
        var filterConfigurationResult = CreateFilterConfiguration();
        factoryAction?.Invoke(filterConfigurationResult);

        return filterConfigurationResult;
    }

    private Humidifier.Glue.ConnectionTypeTypes.FilterConfiguration CreateFilterConfiguration()
    {
        var filterConfigurationResult = new Humidifier.Glue.ConnectionTypeTypes.FilterConfiguration();

        return filterConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Glue.ConnectionTypeTypes.FilterConfiguration result)
    {
        base.CreateChildren(result);

        result.BetweenConfiguration ??= BetweenConfigurationFactory?.Build();
        result.FilterStringConfiguration ??= FilterStringConfigurationFactory?.Build();
    }

} // End Of Class

